command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/failure-propagation-native-preflight-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("failure-propagation-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp aa09b4ee274680a15f8a123f6800c5ff7c9d013c
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  $env:FLYEXPLORER_CHECK_RESULT_PATH=Join-Path $temp "logs\remote-evidence\check-result.json"

  & git checkout 4aa4d438f8e043dcd28b371be8ac9f6e90d42165 -- app/winui/MainWindow.xaml.cpp app/winui/MainWindow.xaml.h app/winui/m23_drag.cpp
  if($LASTEXITCODE -ne 0){throw "historical compile-error fixture checkout failed"}
  & python -X utf8 tools\winui\run_checks.py native-compile --before 72cfa6b962aca2ea351af354091f1f3230deeb91 --head 4aa4d438f8e043dcd28b371be8ac9f6e90d42165 --configuration Release
  $expectedCode=$LASTEXITCODE
  if($expectedCode -eq 0){throw "expected C3779 compile failure was not detected"}
  $payload=Get-Content -Raw -Encoding UTF8 -LiteralPath $env:FLYEXPLORER_CHECK_RESULT_PATH | ConvertFrom-Json
  if(([string]$payload.failure_category) -ne "PRODUCT_BUILD_FAILURE"){throw "compile failure category was not preserved"}
  Write-Host "EXPECTED_NATIVE_COMPILE_FAILURE=PASS"

  & git checkout HEAD -- app/winui/MainWindow.xaml.cpp app/winui/MainWindow.xaml.h app/winui/m23_drag.cpp
  if($LASTEXITCODE -ne 0){throw "fixture restore failed"}
  $out=Join-Path $temp "out"
  if(Test-Path -LiteralPath $out){Remove-Item -LiteralPath $out -Recurse -Force}

  $compileWatch=[Diagnostics.Stopwatch]::StartNew()
  & python -X utf8 tools\winui\run_checks.py native-compile --before 72cfa6b962aca2ea351af354091f1f3230deeb91 --head ef8e2d7a65c03c3727aae625facaf6305d7d9841 --configuration Release
  $compileCode=$LASTEXITCODE
  $compileWatch.Stop()
  if($compileCode -ne 0){throw "valid native compile preflight failed"}
  Write-Host ("NATIVE_COMPILE_PREFLIGHT_SECONDS={0:N1}" -f $compileWatch.Elapsed.TotalSeconds)

  if(Test-Path -LiteralPath $out){Remove-Item -LiteralPath $out -Recurse -Force}
  $buildWatch=[Diagnostics.Stopwatch]::StartNew()
  & python -X utf8 tools\winui\run_checks.py build --configuration Release
  $buildCode=$LASTEXITCODE
  $buildWatch.Stop()
  if($buildCode -ne 0){throw "full Release build failed"}
  Write-Host ("FULL_RELEASE_BUILD_SECONDS={0:N1}" -f $buildWatch.Elapsed.TotalSeconds)
  Write-Host "NATIVE_COMPILE_TO_FULL_BUILD_CONTINUATION=PASS"
  Write-Host "FAILURE_PROPAGATION_NATIVE_PREFLIGHT_INTEGRATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
